// Pega os dados do ViaCEP que vieram no input direto
const viacep = $input.first().json;

// Pega o número diretamente do nó raiz "Recebeu WF 01" com segurança absoluta
let numeroCasa = "";
try {
  const wf01 = $('Recebeu WF 01').first().json;
  numeroCasa = wf01.restante_endereco || wf01.numero || wf01.complemento || "";
} catch (e) {}

// Monta o endereço final juntando o logradouro do ViaCEP com o número da casa
const logradouro = viacep.logradouro || "";
let enderecoFinal = logradouro;

if (numeroCasa) {
  enderecoFinal = `${logradouro}, ${numeroCasa}`;
}

// Monta a query completa para o Nominatim não perder o número
const query = `${enderecoFinal}, ${viacep.bairro || ''}, ${viacep.localidade || ''}, ${viacep.uf || ''}, Brasil`;

return [{
  sucesso: true,
  cep: viacep.cep,
  logradouro: logradouro,
  numero: numeroCasa,
  bairro: viacep.bairro,
  localidade: viacep.localidade,
  uf: viacep.uf,
  cep_via_cep: viacep.cep,
  query_nominatim: query
}];

// Pega todos os dados de entrada de forma segura
const inputItems = $input.all();

if (!inputItems || inputItems.length === 0 || !inputItems[0].json) {
  return [{
    sucesso: false,
    mensagem: "Erro: Nenhum dado de localização foi recebido do mapa. Por favor, tente novamente."
  }];
}

const nomData = inputItems[0].json;
const nom = Array.isArray(nomData) ? nomData[0] : nomData;

// Fallback se o Nominatim não achar latitude/longitude
if (!nom || !nom.lat || !nom.lon) {
  return [{
    sucesso: false,
    mensagem: "Endereço não localizado com precisão suficiente. Por favor, confirme o CEP e o número do imóvel."
  }];
}

// 1. Coordenadas do Cliente
const latCliente = parseFloat(nom.lat);
const lonCliente = parseFloat(nom.lon);

// 2. Coordenadas da Loja (Estrada das Pitas, 187)
const latLoja = -23.5415696; 
const lonLoja = -46.8679597;

// 3. Fórmula de Haversine para Distância (em Km)
function getDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; 
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

const distanciaKm = getDistance(latLoja, lonLoja, latCliente, lonCliente);

// ---> REGRA: LIMITE DE 15KM <--- 
if (distanciaKm > 15) {
  return [{
    sucesso: false,
    mensagem: `Infelizmente, o endereço está a ${distanciaKm.toFixed(1)}km da nossa loja, e nosso raio máximo de entrega é de 15km.`
  }];
}

// 4. Cálculo da Taxa de Entrega (R$ 2,00 por km, Mínimo de R$ 5,00)
const taxaEntrega = Math.max(5, distanciaKm * 2);

// 5. Cálculo do Subtotal e resgate seguro do WF1 (Incluindo o número da casa)
let subtotal = 0;
let cepOriginal = "06449300";
let numeroCasa = "";

try {
  const wf1Node = $('Recebeu WF 01');
  if (wf1Node && wf1Node.first()) {
    const inputWf = wf1Node.first().json;

    // Pega o número da casa/complemento digitado pelo cliente
    numeroCasa = inputWf.restante_endereco || inputWf.numero || "";

    // CEP original
    cepOriginal = inputWf.cep || inputWf.query || "06449300";

    // Subtotal dos itens
    const itens = JSON.parse(inputWf.itens_pendentes_json || '[]');
    subtotal = itens.reduce((acc, item) => acc + (parseFloat(item.preco) * parseInt(item.quantidade)), 0);
  }
} catch (e) {
  // Se falhar, mantém os fallbacks padrão
}

const total = subtotal + taxaEntrega;

// 6. Tratamento blindado do Endereço Validado (Garante o número impresso)
let enderecoBase = nom.display_name || "Endereço validado";
let enderecoFinal = enderecoBase;

if (numeroCasa) {
  // Se o display do OSM ainda não veio com o número, nós injetamos ele para a planilha ficar perfeita
  if (!enderecoBase.includes(numeroCasa)) {
    enderecoFinal = `Estrada das Pitas, ${numeroCasa}, Parque Viana, Barueri - SP`;
  }
}

// 7. Retorno Limpo para a Duda e para o Sheets
return [{
  sucesso: true,
  cep_utilizado: cepOriginal,
  endereco_validado: enderecoFinal,
  distancia_km: parseFloat(distanciaKm.toFixed(2)),
  taxa_entrega: parseFloat(taxaEntrega.toFixed(2)),
  subtotal: parseFloat(subtotal.toFixed(2)),
  total_pedido: parseFloat(total.toFixed(2))
}];
